# Test the formula: g(x) = 0 if even, g(1)=1, g(odd>1) = π(spf(x))
# where π(p) = number of primes ≤ p

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def compute_grundy_brute(n):
    g = [0] * (n + 1)
    for x in range(1, n + 1):
        reachable = set()
        for y in range(1, x + 1):
            if gcd(x, y) == 1:
                reachable.add(g[x - y])
        mex = 0
        while mex in reachable:
            mex += 1
        g[x] = mex
    return g

# Sieve to find spf and primes
MAX_N = 100
spf = list(range(MAX_N + 1))
for i in range(2, int(MAX_N**0.5) + 1):
    if spf[i] == i:  # i is prime
        for j in range(i*i, MAX_N + 1, i):
            if spf[j] == j:
                spf[j] = i

# Count primes up to each number (π function)
pi = [0] * (MAX_N + 1)
count = 0
for i in range(MAX_N + 1):
    if spf[i] == i and i >= 2:  # i is prime
        count += 1
    pi[i] = count

def g_formula(x):
    if x == 0:
        return 0
    if x == 1:
        return 1
    if x % 2 == 0:
        return 0
    # x is odd > 1
    spf_x = spf[x]
    return pi[spf_x]

g_brute = compute_grundy_brute(MAX_N)

print("Testing formula against brute force:")
all_match = True
for x in range(MAX_N + 1):
    brute = g_brute[x]
    formula = g_formula(x)
    if brute != formula:
        print(f"MISMATCH at x={x}: brute={brute}, formula={formula}")
        all_match = False

if all_match:
    print("All matched! Formula is correct!")

# Show some values
print("\nSample values:")
for x in range(1, 31):
    print(f"g({x}) = {g_formula(x)}")
