import sys

# Precompute SPF and pi arrays
MAX_A = 10000001  # 10^7 + 1

# Initialize SPF array
spf = list(range(MAX_A))

# Sieve: mark SPF for all numbers
# Even numbers > 2 have spf = 2
for i in range(4, MAX_A, 2):
    spf[i] = 2

# Sieve for odd primes
for i in range(3, int(MAX_A**0.5) + 1, 2):
    if spf[i] == i:  # i is prime
        for j in range(i*i, MAX_A, 2*i):
            if spf[j] == j:
                spf[j] = i

# Collect primes and compute pi values
# pi[p] for prime p = index of p in primes list (0-indexed) + 1
# Actually pi[p] = count of primes <= p
# We can build this by: for each prime, mark its position

# More efficient: create pi array by iterating and counting
pi = [0] * MAX_A
prime_count = 0
for i in range(MAX_A):
    if spf[i] == i and i >= 2:
        prime_count += 1
    pi[i] = prime_count

# Pre-define get_grundy as inline for speed
def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []
    for _ in range(t):
        n = int(next(iterator))
        xor_sum = 0
        for _ in range(n):
            a = int(next(iterator))
            # Inline get_grundy logic for speed
            if a == 0:
                g = 0
            elif a == 1:
                g = 1
            elif a % 2 == 0:
                g = 0
            else:
                g = pi[spf[a]]
            xor_sum ^= g
        results.append("Alice" if xor_sum > 0 else "Bob")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
